def main():
    parser=argparse.ArgumentParser(description='P3单文件全年复现与中文绘图')
    parser.add_argument('--output',type=Path,default=Path(__file__).resolve().parent/'p3_results')
    parser.add_argument('--method',choices=['all']+METHODS,default='all')
    parser.add_argument('--no-plots',action='store_true',help='跳过绘图，只导出数据与校验')
    args=parser.parse_args()
    args.output.mkdir(parents=True,exist_ok=True)
    if not args.no_plots:configure_style()
    raw=base64.b64decode(INPUT_ZIP_BASE64)
    if hashlib.sha256(raw).hexdigest()!=INPUT_SHA256:raise RuntimeError('内嵌输入数据校验失败，文件可能损坏')
    with tempfile.TemporaryDirectory(prefix='p3_input_') as temporary:
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            for name in ['q2_actual_load_pv.csv','q2_fixed_prices.csv','pv_forecast_10min.csv']:
                Path(temporary,name).write_bytes(archive.read(name))
        load,pv,p,dates=load_inputs(temporary)
        forecasts=load_forecasts(Path(temporary)/'pv_forecast_10min.csv',dates)
    methods=METHODS if args.method=='all' else [args.method]
    frames={};checks={};summary=[]
    for method in methods:
        print('开始策略：'+method,flush=True);started=time.perf_counter()
        dispatch,decisions=run(load,pv,p,dates,forecasts,method)
        checks[method]=verify(dispatch)
        dispatch.to_csv(args.output/(method+'_dispatch.csv'),index=False,encoding='utf-8-sig')
        decisions.to_csv(args.output/(method+'_decisions.csv'),index=False,encoding='utf-8-sig')
        evaluation=dispatch.loc[dispatch.evaluation]
        emergency_events(evaluation).to_csv(args.output/(method+'_emergency_events.csv'),index=False,encoding='utf-8-sig')
        columns=['planned_cost_yuan','adjustment_cost_yuan','emergency_cost_yuan','total_cost_yuan','emergency_kwh','up_kwh','down_kwh','unused_kwh']
        summary.append(dict(method=method,**evaluation[columns].sum().to_dict()))
        frames[method]=dispatch
        print(f'校验通过；评价期总费用 {evaluation.total_cost_yuan.sum():.4f} 元；耗时 {time.perf_counter()-started:.1f} 秒',flush=True)
    pd.DataFrame(summary).to_csv(args.output/'comparison.csv',index=False,encoding='utf-8-sig')
    (args.output/'physics_checks.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf-8')
    (args.output/'parameters.json').write_text(json.dumps(CONFIG,ensure_ascii=False,indent=2),encoding='utf-8')
    if not args.no_plots:
        if args.method=='all':plot_q3_figures(frames,args.output/'figures')
        else:print('单策略模式：不生成三策略对比图。需要三张图请使用默认命令。')
    print('P3: PASS；输出目录：'+str(args.output.resolve()),flush=True)

if __name__=='__main__':
    main()
